WFJ.Data.add("spell", {
  [426019] = { "Mangia (a tuo rischio e pericolo).", "Hai ottenuto un nuovo tipo di vista.", 0xe672e39d, 0x39c94c25, "uu" },
  [426065] = { "I critici di ⟦Holy Shock=Folgore Sacra⟧ e ⟦Flash of Light=Lampo di Luce⟧ riducono di $D2 il tempo di lancio del tuo prossimo ⟦Holy Light=Luce Sacra⟧ entro $D1.", nil, 0x649bcbed, nil, "um" },
  [426072] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [426080] = { nil, "Assorbe energia per creare barriere neutralizzanti.", nil, 0xeefe44e4, "mu" },
  [426084] = { nil, "Avvolto da uno strato raffazzonato e malfermo di trama di ferro protettiva: l'armatura potrebbe staccarsi da un momento all'altro.", nil, 0x19e2e2b3, "mu" },
  [426086] = { nil, "Altamente resistente al caldo e al freddo.", nil, 0x42f19263, "mu" },
  [426097] = { nil, "Non tutti i componenti sono sopravvissuti al trasporto.", nil, 0x4d1719a8, "mu" },
  [426101] = { nil, "L'endoscheletro in iperlega esposto può resistere a quasi ogni assalto.", nil, 0x8778e1d0, "mu" },
  [426157] = { "Aumenta del $N1% tutti i danni da sacro che infliggi, e i tuoi critici in mischia e con gli incantesimi riducono di $D1 il tempo di recupero residuo del tuo incantesimo Esorcismo.", nil, 0xc4a882f0, nil, "um" },
  [426162] = { nil, "Cura di $N1 ogni $D1.", nil, 0x15b97dff, "mu" },
  [426173] = { "Aumenta di $N1 m la portata del tuo Giudizio e del $N2% la tua probabilità di colpire con tutti gli incantesimi.", nil, 0xe1aed3a5, nil, "um" },
  [426174] = { "Ottieni l'abilità Malleable Protection:\n\n$I1\nOra puoi agire durante Protezione Divina e la sua durata aumenta del $N1%, ma invece di renderti immune riduce solo del $N2% i danni che subisci. Inoltre, attivare Scudo Benedetto ti fornisce anche $N3 potenza d'attacco per ogni punto della tua abilità in difesa oltre $N4, per $D1.", nil, 0x00244963, nil, "um" },
  [426175] = { "Incidi sulla tua cintura la runa Malleable Protection:\n\n$I1\nOra puoi agire durante Protezione Divina e la sua durata aumenta del $N1%, ma invece di renderti immune riduce solo del $N2% i danni che subisci. Inoltre, attivare Scudo Benedetto ti fornisce anche $N3 potenza d'attacco per ogni punto della tua abilità in difesa oltre $N4, per $D1.", nil, 0x523ac40a, nil, "um" },
  [426179] = { "Ottieni l'abilità Infusione di Luce:\n\n$I1\nI critici di Folgore Sacra e Lampo di Luce riducono di $D2 il tempo di lancio del tuo prossimo Luce Sacra entro $D1.", nil, 0x58b745f4, nil, "um" },
  [426180] = { "Incidi sulla tua cintura la runa Infusione di Luce:\n\n$I1\nI critici di Folgore Sacra e Lampo di Luce riducono di $D2 il tempo di lancio del tuo prossimo Luce Sacra entro $D1.", nil, 0x4905da9b, nil, "um" },
  [426192] = { nil, "Ma ai murloc serve davvero respirare sott'acqua?", nil, 0x90149cf9, "mu" },
  [426195] = { "Quando viene attivata, questa abilità aumenta temporaneamente del $N1% la tua salute massima per $D1. Quando l'effetto termina, la salute aggiuntiva va perduta. Inoltre, durante Metamorfosi, Vendetta fa sì che le tue ali rallentino la tua caduta.", "Salute aumentata del $N1% del massimo e velocità di caduta rallentata durante Metamorfosi.", 0x56419bc8, 0x7d0d7712, "uu" },
  [426199] = { "Infligge $N1 danni da ombra ogni $D1.", "Infligge $N1 danni da ombra ogni $D1.", 0x89116fee, 0x89116fee, "uu" },
  [426243] = { "Applicare Corruzione, Immolazione, ⟦Curse of Agony=Maledizione dell'Agonia⟧, Afflizione Instabile, Ombrofuoco o Aspirazione della Vita ti fa infliggere istantaneamente al bersaglio danni pari a un impulso dei danni periodici dell'incantesimo. Rinnovare uno di questi incantesimi quando gli restano meno di $N1 s di durata ti fa infliggere istantaneamente al bersaglio danni pari ai danni periodici rimanenti dell'incantesimo.", nil, 0x744ce5b3, nil, "um" },
  [426257] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [426301] = { "I danni inflitti da te o dal demone che hai evocato hanno il $N1% di probabilità di aumentare del $N2% i danni inflitti dall'altro per $D1.", "I danni inflitti da te o dal demone che hai evocato hanno il $N1% di probabilità di aumentare del $N2% i danni inflitti dall'altro per $D1.", 0x68930328, 0x68930328, "uu" },
  [426303] = { "Aumenta del $N1% tutti i danni inflitti.", "Aumenta del $N1% tutti i danni inflitti.", 0xbb0dd240, 0xbb0dd240, "uu" },
  [426311] = { "Aumenta del $N1% tutti i danni da fuoco inflitti.", "Aumenta del $N1% tutti i danni da fuoco inflitti.", 0x7f6cf186, 0x7ff627f2, "uu" },
  [426316] = { "Colpire un nemico con Conflagrazione aumenta del $N1% tutti i danni da ombra che infliggi per $D1, e colpire un nemico con Combustione dell'Ombra aumenta del $N3% tutti i danni da fuoco che infliggi per $D2. Inoltre, Conflagrazione ha il $N5% di probabilità di non consumare Immolazione, e Combustione dell'Ombra ha il $N6% di probabilità di restituirti istantaneamente un frammento d'anima.", nil, 0xa8ba88f4, nil, "um" },
  [426320] = { "Brucia il nemico infliggendo $N1 danni da ombrofuoco e poi altri $N2 danni da ombrofuoco in $D1.\n\nOmbrofuoco attiva e beneficia di tutti gli effetti che modificano Immolazione o interagiscono con essa, o con gli incantesimi di Afflizione, Distruzione, fuoco od ombra, ma su un bersaglio può essere attivo un solo Immolazione od Ombrofuoco per Stregone. Inoltre, Ombrofuoco può attivare il tuo talento ⟦Shadow Bolt=Dardo d'Ombra⟧ Migliorato e gli fa ottenere $N4 cariche aggiuntive.", "$N1 danni da ombrofuoco ogni $N2 s.", 0xae243044, 0x0b858fca, "uu" },
  [426325] = { nil, "$N1 danni da fuoco ogni $N2 s.", nil, 0x341a73be, "mu" },
  [426359] = { "Decifra gli appunti dell'incantesimo con un Comprehension Charm per apprendere un nuovo incantesimo d'incisione.", nil, 0x7ccaad21, nil, "um" },
  [426442] = { "Ottieni l'abilità Invocation:\n\n$I1\nApplicare Corruzione, Immolazione, Maledizione dell'Agonia, Afflizione Instabile, Ombrofuoco o Aspirazione della Vita ti fa infliggere istantaneamente al bersaglio danni pari a un impulso dei danni periodici dell'incantesimo. Rinnovare uno di questi incantesimi quando gli restano meno di $N1 s di durata ti fa infliggere istantaneamente al bersaglio danni pari ai danni periodici rimanenti dell'incantesimo.", nil, 0x4bcef489, nil, "um" },
  [426443] = { "Incidi sulla tua cintura la runa Invocation:\n\n$I1\nApplicare Corruzione, Immolazione, Maledizione dell'Agonia, Afflizione Instabile, Ombrofuoco o Aspirazione della Vita ti fa infliggere istantaneamente al bersaglio danni pari a un impulso dei danni periodici dell'incantesimo. Rinnovare uno di questi incantesimi quando gli restano meno di $N1 s di durata ti fa infliggere istantaneamente al bersaglio danni pari ai danni periodici rimanenti dell'incantesimo.", nil, 0xf02be364, nil, "um" },
  [426444] = { "Ottieni l'abilità Rito della Sinergia:\n\n$I1\nI danni inflitti da te o dal demone che hai evocato hanno il $N1% di probabilità di aumentare del $N2% i danni inflitti dall'altro per $D1.", nil, 0xed3c384e, nil, "um" },
  [426445] = { "Incidi sulla tua cintura la runa Rito della Sinergia:\n\n$I1\nI danni inflitti da te o dal demone che hai evocato hanno il $N1% di probabilità di aumentare del $N2% i danni inflitti dall'altro per $D1.", nil, 0x6962f950, nil, "um" },
  [426449] = { "Ottieni l'abilità Ombra e Fiamma:\n\n$I1\nColpire un nemico con Conflagrazione aumenta del $N1% tutti i danni da ombra che infliggi per $D1, e colpire un nemico con Combustione dell'Ombra aumenta del $N3% tutti i danni da fuoco che infliggi per $D2. Inoltre, Conflagrazione ha il $N5% di probabilità di non consumare Immolazione, e Combustione dell'Ombra ha il $N6% di probabilità di restituirti istantaneamente un frammento d'anima.", nil, 0xac371e1e, nil, "um" },
  [426452] = { "Incidi sulla tua cintura la runa Ombra e Fiamma:\n\n$I1\nColpire un nemico con Conflagrazione aumenta del $N1% tutti i danni da ombra che infliggi per $D1, e colpire un nemico con Combustione dell'Ombra aumenta del $N3% tutti i danni da fuoco che infliggi per $D2. Inoltre, Conflagrazione ha il $N5% di probabilità di non consumare Immolazione, e Combustione dell'Ombra ha il $N6% di probabilità di restituirti istantaneamente un frammento d'anima.", nil, 0x6e71e40a, nil, "um" },
  [426454] = { "Ottieni l'abilità Ombrofuoco:\n\n$I1\nBrucia il nemico infliggendo $N1 danni da ombrofuoco e poi altri $N2 danni da ombrofuoco in $D1.\n\nOmbrofuoco attiva e beneficia di tutti gli effetti che modificano Immolazione o interagiscono con essa, o con gli incantesimi di Afflizione, Distruzione, fuoco od ombra, ma su un bersaglio può essere attivo un solo Immolazione od Ombrofuoco per Stregone. Inoltre, Ombrofuoco può attivare il tuo talento Dardo d'Ombra Migliorato e gli fa ottenere $N4 cariche aggiuntive.", nil, 0x0c00a94d, nil, "um" },
  [426467] = { "Incidi sui tuoi stivali la runa Ombrofuoco:\n\n$I1\nBrucia il nemico infliggendo $N1 danni da ombrofuoco e poi altri $N2 danni da ombrofuoco in $D1.\n\nOmbrofuoco attiva e beneficia di tutti gli effetti che modificano Immolazione o interagiscono con essa, o con gli incantesimi di Afflizione, Distruzione, fuoco od ombra, ma su un bersaglio può essere attivo un solo Immolazione od Ombrofuoco per Stregone. Inoltre, Ombrofuoco può attivare il tuo talento Dardo d'Ombra Migliorato e gli fa ottenere $N4 cariche aggiuntive.", nil, 0xc47d2fb0, nil, "um" },
  [426469] = { "Ottieni l'abilità Vendetta:\n\n$I1\nQuando viene attivata, questa abilità aumenta temporaneamente del $N1% la tua salute massima per $D1. Quando l'effetto termina, la salute aggiuntiva va perduta. Inoltre, durante Metamorfosi, Vendetta fa sì che le tue ali rallentino la tua caduta.", nil, 0x170741ae, nil, "um" },
  [426470] = { "Incidi sul tuo elmo la runa Vendetta:\n\n$I1\nQuando viene attivata, questa abilità aumenta temporaneamente del $N1% la tua salute massima per $D1. Quando l'effetto termina, la salute aggiuntiva va perduta. Inoltre, durante Metamorfosi, Vendetta fa sì che le tue ali rallentino la tua caduta.", nil, 0xb6b931d6, nil, "um" },
  [426489] = { nil, "Aumenta del $N1% tutti i danni inflitti.", nil, 0xd6406ebb, "mu" },
  [426490] = { "Lancia un grido di raccolta che aumenta del $N2% la salute massima di tutti i membri del gruppo e dell'incursione entro $N1 m per $D1.", "Salute aumentata del $N1% del massimo.", 0x27c70783, 0xf305c695, "uu" },
  [426491] = { "Incidi sui tuoi stivali la runa Chiamata a Raccolta:\n\n$I1\nLancia un grido di raccolta che aumenta del $N2% la salute massima di tutti i membri del gruppo e dell'incursione entro $N1 m per $D1.", nil, 0xec8cc0d9, nil, "um" },
  [426492] = { "Ottieni l'abilità Chiamata a Raccolta:\n\n$I1\nLancia un grido di raccolta che aumenta del $N2% la salute massima di tutti i membri del gruppo e dell'incursione entro $N1 m per $D1.", nil, 0x04519817, nil, "um" },
  [426495] = { nil, "Le ombre ti stringono le gambe, riducendo la velocità di movimento e infliggendo $N1 danni ogni $D1.", nil, 0x81e391d3, "mu" },
  [426597] = { "..", nil, 0x000017b8, nil, "um" },
  [426604] = { nil, "Riavvio del sistema in corso.", nil, 0x833b5b1e, "mu" },
  [426606] = { "Permette a chi lo beve di parlare con il cadavere di qualcuno che ha questioni in sospeso nel mondo dei vivi. Potrebbe anche curare l'indigestione.", "Permette a chi lo beve di parlare con il cadavere di qualcuno che ha questioni in sospeso nel mondo dei vivi. Potrebbe anche curare l'indigestione.", 0x440274f1, 0x440274f1, "uu" },
  [426612] = { "Contempla una visione al falò di Je'neu.", nil, 0x8f6faa55, nil, "um" },
  [426633] = { "Fai un'offerta di sangue e libera l'anima rinchiusa.", nil, 0x38180547, nil, "um" },
  [426640] = { nil, "È stato compiuto un sacrificio adeguato.", nil, 0x8a285689, "mu" },
  [426668] = { "Evoca $N1 Stone Rumblers che affiancano l'incantatore fino al congedo.", nil, 0x36bf232d, nil, "um" },
  [426694] = { "Assume la forma d'orso per $D1, aumentando l'Armatura e la salute e permettendo di usare varie abilità dell'orso.", "In forma d'orso.\nArmatura aumentata del $N1%, salute aumentata di $N2 e potenza d'attacco aumentata di $N3.", 0x827ae877, 0xa64e022f, "uu" },
  [426754] = { "Fai un'offerta di sangue per liberare questa Tortured Soul.", nil, 0x72038d21, nil, "um" },
  [426764] = { nil, "Demotivato... Senza fatica non si ottiene nulla.", nil, 0xa0ac7857, "mu" },
  [426811] = { nil, "Gli alleati entro $N1 m da un comandante sul campo di battaglia ottengono il $N2% di salute in più e il $N3% di danni in più.", nil, 0x5a25079a, "mu" },
  [426821] = { "Si affida alla magia della natura per curare un alleato.", nil, 0xa861c49b, nil, "um" },
  [426917] = { nil, "Vulnerabile ai danni da fuoco.", nil, 0x357449a4, "mu" },
  [426923] = { nil, "Vulnerabile ai danni da gelo.", nil, 0x52332012, "mu" },
  [426925] = { nil, "Vulnerabile ai danni da natura.", nil, 0x6691b417, "mu" },
  [426940] = { "Scateni la tua furia, aumentando del $N1% la tua potenza d'attacco per $D1. Questa abilità si può usare solo mentre sei infuriato.", "Aumenta la potenza d'attacco del $N1%.", 0x507c8c0a, 0x39534167, "uu" },
  [426953] = { "Ogni volta che la tua abilità Squartamento infligge danni, la tua abilità Dominazione si attiva per $D1 o per $N2 attacco. Questo effetto non può verificarsi più di una volta ogni $D2.", nil, 0x8d278e91, nil, "um" },
  [426969] = { nil, "Permette di usare Dominazione.", nil, 0x77befb9b, "mu" },
  [426972] = { "Concentra il tuo sguardo protettivo su un membro del gruppo o dell'incursione, riducendo del $N1% i danni che subisce e trasferendo a te il $N2% della minaccia che genera. Inoltre, ogni volta che viene colpito da un attacco, il tempo di recupero della tua Provocazione si azzera. Dura $D1. Questo effetto può essere attivo su un solo bersaglio alla volta.", "Danni subiti ridotti del $N1% e il $N2% di tutta la minaccia trasferito al Guerriero.", 0x4720bf0a, 0xa1c1c2ab, "uu" },
  [426975] = { nil, "Danni subiti ridotti del $N1% e il $N2% di tutta la minaccia trasferito al Guerriero.", nil, 0x4c5cf7a8, "mu" },
  [426978] = { "Quando le tue abilità Sfondamento e Rivincita infliggono danni, hanno il $N1% di probabilità di azzerare il tempo di recupero della tua abilità ⟦Shield Slam=Colpo di Scudo⟧ e di ridurne del $N2% il costo in rabbia per $D1.", nil, 0xd3189dc2, nil, "um" },
  [426979] = { nil, "Costo in rabbia di ⟦Shield Slam=Colpo di Scudo⟧ ridotto del $N1%.", nil, 0xdde900a0, "mu" },
  [426980] = { "Aumenta del $N1% tutti i danni fisici che infliggi mentre hai uno scudo equipaggiato e riduce del $N2% la durata di tutti gli effetti di disarmo usati contro di te. Non si cumula con altri effetti che riducono la durata del disarmo.", nil, 0x23eaab02, nil, "um" },
})
